let subtitleDragMode=false,subtitleDrag=null;
const subtitleFieldNames={x:'水平位置（%）',y:'垂直位置（%）',width:'字幕框宽度（%）',fontSize:'文字大小'};
function subtitleFields(value,scope){return `<div class="field-row">${Object.entries(subtitleFieldNames).map(([key,label])=>`<div class="field"><label>${label}</label><input type="number" min="${key==='width'?25:key==='fontSize'?16:0}" max="${key==='width'?98:key==='fontSize'?48:100}" step="1" value="${Math.round(value[key])}" data-subtitle="${key}" data-scope="${scope}"></div>`).join('')}</div><div class="field"><label>文字对齐</label><select data-subtitle="align" data-scope="${scope}">${optionList({left:'左对齐',center:'居中',right:'右对齐'},value.align)}</select></div>`}
const layoutEditor=editor,layoutInspector=drawInspector,layoutDrawStage=drawStage;
editor=function(){return layoutEditor().replace('<span class="micro">剧情编排</span>','<span class="micro">剧情编排</span><button class="btn small" data-action="subtitle-defaults">全局字幕布局</button>')};
drawStage=function(force=false){layoutDrawStage(force);$('#stage')?.classList.toggle('subtitle-drag-mode',subtitleDragMode&&!playing)};
drawInspector=function(){layoutInspector();const b=block();if(!b||!['dialogue','narration','choice'].includes(b.type))return;$('#inspector').insertAdjacentHTML('beforeend',`<section class="subtitle-settings"><h3>字幕布局</h3><label class="subtitle-check"><input type="checkbox" data-subtitle-custom ${b.subtitle?'checked':''}> 本句使用独立布局（调整数值时自动启用）</label>${subtitleFields(KotobaCore.subtitleLayout(project,b),'block')}<div class="subtitle-presets"><button class="btn small" data-action="subtitle-preset" data-id="top">顶部</button><button class="btn small" data-action="subtitle-preset" data-id="middle">中部</button><button class="btn small" data-action="subtitle-preset" data-id="bottom">底部</button><button class="btn small ${subtitleDragMode?'primary':''}" data-action="subtitle-drag">${subtitleDragMode?'结束拖动':'在画面中拖动'}</button></div><p class="field-note">${b.subtitle?'仅影响当前剧情块。取消勾选可恢复工程默认布局。':'当前沿用工程默认布局；修改本面板只为这一句建立独立布局。'}角色名始终位于字幕框上方。</p></section>`)};
function subtitleDefaultsDialog(){dialog('工程默认字幕布局',`<p>调整整部作品的默认字幕位置。可在单句属性里设置例外。</p>${subtitleFields(KotobaCore.subtitleLayout(project),'project')}<p class="field-note">位置按画面百分比保存，窗口缩放和离线试玩会保持相同布局。</p>`,'完成',()=>{})}
function updateSubtitle(key,value,scope){const b=block();change(()=>{const target=scope==='block'&&b?b:project;target.subtitle={...KotobaCore.subtitleLayout(project,scope==='block'?b:null),[key]:key==='align'?value:Number(value)};target.subtitle=KotobaCore.subtitleLayout({subtitle:target.subtitle})})}
document.addEventListener('change',e=>{if(e.target.dataset.subtitle){updateSubtitle(e.target.dataset.subtitle,e.target.value,e.target.dataset.scope)}else if(e.target.matches('[data-subtitle-custom]'))change(()=>{if(e.target.checked)block().subtitle={...KotobaCore.subtitleLayout(project,block())};else delete block().subtitle})});
async function pasteConversionText(){const area=$('#conversionSource');if(!area)return;try{const text=await window.desktop.clipboardText();if(!text){notify('剪贴板中没有文本');return}if(new TextEncoder().encode(text).length>2*1024*1024){notify('文本超过 2 MB，请分段粘贴');return}if(!area.isConnected)return;area.setRangeText(text,area.selectionStart,area.selectionEnd,'end');area.dispatchEvent(new Event('input',{bubbles:true}));area.focus();notify('已粘贴文本，可点击「识别并预览」')}catch{notify('读取剪贴板失败，可在输入框内按 Ctrl+V 粘贴')}}
const layoutConversionView=conversionView;
conversionView=function(){return layoutConversionView().replace('<span class="panel-title">普通剧本文本</span>','<span class="panel-title">普通剧本文本</span><button class="btn primary small" data-action="paste-text">粘贴文本</button>').replace('placeholder="旁白直接写在一行','aria-label="粘贴或输入剧本文本" placeholder="可点击粘贴文本，或按 Ctrl+V 粘贴。\n旁白直接写在一行')};
document.addEventListener('click',e=>{const control=e.target.closest('[data-action]'),action=control?.dataset.action;if(['subtitle-defaults','subtitle-drag','subtitle-preset','paste-text'].includes(action)){e.preventDefault();e.stopImmediatePropagation();if(action==='subtitle-defaults')subtitleDefaultsDialog();if(action==='paste-text')pasteConversionText();if(action==='subtitle-drag'){subtitleDragMode=!subtitleDragMode;if(typeof portraitDragMode!=='undefined')portraitDragMode=false;draw();if(subtitleDragMode)notify('拖动预览中的字幕框即可移动；不会开始试演')}if(action==='subtitle-preset')updateSubtitle('y',{top:18,middle:50,bottom:82}[control.dataset.id],'block');return}if(subtitleDragMode&&!playing&&e.target.closest('#stage')){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('pointerdown',e=>{if(!subtitleDragMode||playing||e.button!==0||!e.target.closest('#stage .dialogue'))return;e.preventDefault();e.stopImmediatePropagation();const stage=$('#stage'),b=block();if(!b||!['dialogue','narration','choice'].includes(b.type))return;snapshot();const layout=KotobaCore.subtitleLayout(project,b);b.subtitle={...layout};subtitleDrag={pointerId:e.pointerId,block:b,startX:e.clientX,startY:e.clientY,layout,rect:stage.getBoundingClientRect(),stage};stage.setPointerCapture(e.pointerId)},true);
document.addEventListener('pointermove',e=>{const d=subtitleDrag;if(!d||d.pointerId!==e.pointerId)return;e.preventDefault();d.block.subtitle={...d.layout,x:Math.min(100,Math.max(0,d.layout.x+(e.clientX-d.startX)/d.rect.width*100)),y:Math.min(100,Math.max(0,d.layout.y+(e.clientY-d.startY)/d.rect.height*100))};drawStage()},true);
function finishSubtitleDrag(e){const d=subtitleDrag;if(!d||d.pointerId!==e.pointerId)return;subtitleDrag=null;if(d.stage.hasPointerCapture(e.pointerId))d.stage.releasePointerCapture(e.pointerId);save();draw()}
document.addEventListener('pointerup',finishSubtitleDrag,true);document.addEventListener('pointercancel',finishSubtitleDrag,true);
draw();
